// Generated by /ship coverage audit (Claude) — 2026-10-16
// Value: protects=the /sessions lock-queue panel: attendance shown as the lock rule (roster - missing)/roster, Khóa only when lockable, Điểm danh by attendance.mark, N+ at the cap, the list's readiness words and tones ("Sẵn sàng khóa" as on the rows), missing attendance and an empty roster counted apart in the header, "Lọc danh sách" bounded at today when given (the list's "Chờ khóa" chip URL), and on the list path it is given (the /dev preview's own);
// fails_when=walk-ins inflate the numerator, an empty roster offers Khóa, attendance.mark stops gating Điểm danh, the canLock fallback is lost, a full page drops its +, the panel's ready badge drifts from the list's, an empty roster is reported as missing attendance, the filter link loses (or wrongly gains) its to=today, or ignores listPath / breaks a path that already has a query;
// why_new=step 14a changes the panel and only the route/dev preview render it, with no assertion on it; seam=none; no_claim=does not prove the queue RPC's counts
import { cleanup, render, screen, within } from "@testing-library/react";
import { afterEach, describe, expect, it } from "vitest";

import { UnlockedSessionQueue } from "@/features/sessions/components/unlocked-session-queue";
import { getSessionLockReadinessLabel } from "@/features/sessions/session-directory-models";
import type { UnlockedSessionQueueItem } from "@/features/sessions/unlocked-sessions-data";

afterEach(cleanup);

const item = (patch: Partial<UnlockedSessionQueueItem> & Pick<UnlockedSessionQueueItem, "classCode" | "id">): UnlockedSessionQueueItem => ({
  attendanceCount: 0,
  autoLockOn: null,
  classId: `class-${patch.classCode}`,
  className: `Toán ${patch.classCode}`,
  completedAt: "2026-10-15T03:00:00Z",
  completedByName: null,
  daysSinceCompleted: 1,
  endTime: "10:00:00",
  missingAttendanceCount: 0,
  rosterCount: 15,
  sessionDate: "2026-10-12",
  sessionKind: "regular",
  startTime: "08:00:00",
  ...patch,
});

// 17 attendance rows on a 15-student roster: two walk-ins (additional_study).
const ready = item({ attendanceCount: 17, autoLockOn: "2026-10-18", classCode: "7B", id: "s-ready" });
const missing = item({ attendanceCount: 13, classCode: "9C", id: "s-missing", missingAttendanceCount: 2 });
const noRoster = item({ attendanceCount: 0, classCode: "8A", id: "s-empty", rosterCount: 0 });

const panel = () => screen.getByRole("region", { name: /buổi đã hoàn thành chưa khóa/ });
const row = (code: string) => {
  const match = within(panel()).getAllByRole("listitem").find((entry) => entry.textContent?.startsWith(`${code} ·`));
  if (!match) throw new Error(`No queue row for ${code}`);
  return match;
};

describe("Unlocked session queue (step 14a)", () => {
  it("shows attendance as the lock rule, never the walk-in-inflated row count", () => {
    render(<UnlockedSessionQueue canLock canMarkAttendance queue={{ autoLockAfterDays: 3, items: [ready, missing, noRoster] }} />);
    expect(row("7B")).toHaveTextContent("Điểm danh 15/15");
    expect(row("7B")).not.toHaveTextContent("17/15");
    expect(row("7B")).toHaveTextContent("Tự khóa 18/10/2026");
    expect(row("9C")).toHaveTextContent("Điểm danh 13/15");
    expect(row("9C")).toHaveTextContent("Thiếu 2 điểm danh");
    expect(row("8A")).toHaveTextContent("Không có học sinh");
    expect(row("8A")).not.toHaveTextContent(/Điểm danh \d/);
  });

  it("offers Khóa only for a lockable session and Điểm danh only with attendance.mark", () => {
    const view = render(<UnlockedSessionQueue canLock canMarkAttendance={false} queue={{ autoLockAfterDays: 3, items: [ready, missing, noRoster] }} />);
    expect(within(row("7B")).getByRole("link", { name: /^Khóa buổi 7B/ })).toHaveAttribute("href", "/sessions/s-ready");
    expect(within(row("9C")).queryByRole("link", { name: /^Điểm danh/ })).not.toBeInTheDocument();
    expect(within(row("9C")).queryByRole("link", { name: /^Khóa/ })).not.toBeInTheDocument();
    // An empty roster can never be locked (the RPC refuses it), so no Khóa link.
    expect(within(row("8A")).queryByRole("link", { name: /^Khóa/ })).not.toBeInTheDocument();

    view.rerender(<UnlockedSessionQueue canLock={false} canMarkAttendance queue={{ autoLockAfterDays: 3, items: [ready, missing, noRoster] }} />);
    expect(within(row("9C")).getByRole("link", { name: /^Điểm danh buổi 9C/ })).toHaveAttribute("href", "/sessions/s-missing");
    expect(within(panel()).queryByRole("link", { name: /^Khóa/ })).not.toBeInTheDocument();
  });

  it("keeps the lock permission gating both links when attendance.mark is not passed", () => {
    const view = render(<UnlockedSessionQueue canLock queue={{ autoLockAfterDays: 3, items: [ready, missing] }} />);
    expect(within(row("7B")).getByRole("link", { name: /^Khóa/ })).toHaveAttribute("href", "/sessions/s-ready");
    expect(within(row("9C")).getByRole("link", { name: /^Điểm danh/ })).toHaveAttribute("href", "/sessions/s-missing");

    view.rerender(<UnlockedSessionQueue canLock={false} queue={{ autoLockAfterDays: 3, items: [ready, missing] }} />);
    expect(within(row("7B")).queryByRole("link", { name: /^Khóa/ })).not.toBeInTheDocument();
    expect(within(row("9C")).queryByRole("link", { name: /^Điểm danh/ })).not.toBeInTheDocument();
  });

  it("marks the counts as a lower bound only when the queue filled the requested limit", () => {
    const items = Array.from({ length: 9 }, (_, index) => item({ classCode: `C${index}`, id: `s-${index}` }));
    const view = render(<UnlockedSessionQueue canLock limit={9} queue={{ autoLockAfterDays: 0, items }} />);
    expect(screen.getByRole("heading", { level: 2 })).toHaveTextContent("9+ buổi đã hoàn thành chưa khóa");
    expect(screen.getByText("Còn 1+ buổi khác chờ khóa.")).toBeInTheDocument();
    expect(within(panel()).getAllByRole("listitem")).toHaveLength(8);

    view.rerender(<UnlockedSessionQueue canLock limit={200} queue={{ autoLockAfterDays: 0, items }} />);
    expect(screen.getByRole("heading", { level: 2 })).toHaveTextContent(/^9 buổi đã hoàn thành chưa khóa$/);
    expect(screen.getByText("Còn 1 buổi khác chờ khóa.")).toBeInTheDocument();
  });

  it("uses the list's readiness badge and counts missing attendance apart from an empty roster", () => {
    const plainReady = item({ classCode: "6A", id: "s-plain" });
    const missingToo = item({ classCode: "9D", id: "s-missing-2", missingAttendanceCount: 1 });
    const view = render(<UnlockedSessionQueue canLock queue={{ autoLockAfterDays: 3, items: [plainReady, missing, missingToo, noRoster] }} />);
    const badge = within(row("6A")).getByText("Sẵn sàng khóa");
    const { tone } = getSessionLockReadinessLabel({ kind: "ready" });
    expect(badge).toHaveClass(`text-${tone}`);
    expect(panel()).toHaveTextContent("2 buổi còn thiếu điểm danh, 1 buổi không có học sinh nên không thể khóa.");

    view.rerender(<UnlockedSessionQueue canLock queue={{ autoLockAfterDays: 3, items: [plainReady, noRoster] }} />);
    expect(panel()).toHaveTextContent("1 buổi không có học sinh nên không thể khóa.");
    expect(panel()).not.toHaveTextContent("thiếu điểm danh");

    view.rerender(<UnlockedSessionQueue canLock queue={{ autoLockAfterDays: 3, items: [plainReady, missing] }} />);
    expect(panel()).toHaveTextContent("1 buổi còn thiếu điểm danh nên không thể khóa.");
    expect(panel()).not.toHaveTextContent("không có học sinh");
  });

  it("bounds Lọc danh sách at today only when the page gives today", () => {
    const view = render(<UnlockedSessionQueue canLock queue={{ autoLockAfterDays: 3, items: [ready] }} today="2026-10-16" />);
    expect(screen.getByRole("link", { name: "Lọc danh sách" })).toHaveAttribute("href", "/sessions?status=completed&lock=unlocked&to=2026-10-16");
    view.rerender(<UnlockedSessionQueue canLock queue={{ autoLockAfterDays: 3, items: [ready] }} />);
    expect(screen.getByRole("link", { name: "Lọc danh sách" })).toHaveAttribute("href", "/sessions?status=completed&lock=unlocked");
  });

  it("points Lọc danh sách at the given list path, joining an existing query with &", () => {
    const view = render(<UnlockedSessionQueue canLock listPath="/dev/lists?view=sessions" queue={{ autoLockAfterDays: 3, items: [ready] }} today="2026-10-16" />);
    expect(screen.getByRole("link", { name: "Lọc danh sách" })).toHaveAttribute("href", "/dev/lists?view=sessions&status=completed&lock=unlocked&to=2026-10-16");
    view.rerender(<UnlockedSessionQueue canLock listPath="/dev/lists" queue={{ autoLockAfterDays: 3, items: [ready] }} />);
    expect(screen.getByRole("link", { name: "Lọc danh sách" })).toHaveAttribute("href", "/dev/lists?status=completed&lock=unlocked");
  });

  it("renders nothing for an empty queue", () => {
    const { container } = render(<UnlockedSessionQueue canLock limit={200} queue={{ autoLockAfterDays: 3, items: [] }} />);
    expect(container).toBeEmptyDOMElement();
  });
});
